B.aC1=s(["\u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u0629 \u0641\u064a \u0627\u0644\u062c\u0648\u0627\u0628 \u062a\u064f\u0641\u062a\u062d \u0641\u064a \u0627\u0644\u0645\u0635\u062d\u0641 \u0639\u0644\u0649 \u0645\u0648\u0636\u0639\u0647\u0627.","\xab\u0627\u0644\u0623\u0643\u062b\u0631 \u0628\u062d\u062b\u0627\u064b \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\xbb \u0641\u064a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629.","\u0632\u0631 \u0635\u063a\u064a\u0631 \xab\u0623\u0643\u0645\u0644 \u0645\u0646 \u062d\u064a\u062b \u062a\u0648\u0642\u0641\u062a\xbb \u0641\u064a \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0637\u0648\u064a\u0644\u0629\u060c \u0648\u0634\u0631\u064a\u0637 \u064a\u0628\u064a\u0651\u0646 \u0643\u0645 \u0642\u0631\u0623\u062a.","\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0644\u064a\u0644\u064a \u0627\u0644\u062a\u0644\u0642\u0627\u0626\u064a \u0628\u0639\u062f \u0627\u0644\u0645\u063a\u0631\u0628 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a)."],t.s)
B.b4O=new A.a_("3.1.0",B.aC1)
B.aBV=s(["\u0627\u0644\u0645\u0635\u062d\u0641: \u0628\u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0639\u062b\u0645\u0627\u0646\u064a\u060c \u0635\u0641\u062d\u0629 \u0635\u0641\u062d\u0629 \u0643\u0627\u0644\u0645\u0635\u062d\u0641 \u0627\u0644\u0648\u0631\u0642\u064a\u060c \u0645\u0639 \u0627\u0644\u0641\u0647\u0631\u0633 \u0648\u0627\u0644\u0628\u062d\u062b.","\u0627\u0636\u063a\u0637 \u0645\u0637\u0648\u0644\u0627\u064b \u0639\u0644\u0649 \u0623\u064a \u0622\u064a\u0629: \u0627\u0644\u062a\u0641\u0633\u064a\u0631 \u0627\u0644\u0645\u064a\u0633\u0631\u060c \u0648\u0639\u0644\u0627\u0645\u0627\u062a \u0645\u0644\u0648\u0651\u0646\u0629 \u062a\u062d\u0641\u0638 \u0648\u0642\u062a\u0647\u0627.","\u0627\u0644\u0623\u0630\u0643\u0627\u0631: \xab\u062d\u0635\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\xbb \u0643\u0627\u0645\u0644\u0627\u064b \u0628\u062a\u0631\u062a\u064a\u0628\u0647\u060c \u0645\u0639 \u0639\u062f\u0651\u0627\u062f \u0627\u0644\u062a\u0633\u0628\u064a\u062d.","\u0634\u0631\u064a\u0637 \u0633\u0641\u0644\u064a \u062c\u062f\u064a\u062f: \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629\u060c \u0627\u0644\u0645\u0635\u062d\u0641\u060c \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0627\u062a\u060c \u0627\u0644\u0643\u062a\u0628\u060c \u0627\u0644\u0645\u0632\u064a\u062f.","\u0627\u0644\u0628\u062d\u062b \u064a\u064f\u0641\u062a\u062d \u0645\u0646 \u062e\u0627\u0646\u0629 \u0627\u0644\u0628\u062d\u062b \u0623\u0639\u0644\u0649 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629.","\u0631\u0648\u0627\u0628\u0637 \u0642\u0635\u064a\u0631\u0629 \u0644\u0644\u0623\u062c\u0648\u0628\u0629\u060c \u0648\u0631\u0645\u0632 QR \u0641\u064a \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u0635\u0648\u0651\u0631\u0629."],t.s)
B.b5I=new A.a_("3.0.0",B.aBV)
B.aCb=s(["\u0627\u0644\u0628\u062d\u062b \u0635\u0627\u0631 \u0623\u062f\u0642: \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u062a\u064a \u062a\u0628\u062d\u062b \u0639\u0646\u0647\u0627 \u0641\u0642\u0637\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u0641\u064a \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0623\u0648 \u0627\u0644\u0633\u0624\u0627\u0644 \u064a\u0623\u062a\u064a \u0623\u0648\u0644\u0627\u064b.","\xab\u0628\u062d\u062b \u0628\u0627\u0644\u0645\u0639\u0646\u0649\xbb \u0632\u0631 \u0627\u062e\u062a\u064a\u0627\u0631\u064a \u0641\u064a \u0635\u0641\u062d\u0629 \u0627\u0644\u0628\u062d\u062b\u060c \u0645\u0639 \u062a\u0635\u0641\u064a\u0629: \u0623\u062c\u0648\u0628\u0629 \u0623\u0648 \u0645\u0642\u0627\u0644\u0627\u062a.","\u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u0635\u0648\u0651\u0631\u0629 \u062a\u062d\u0645\u0644 \u0627\u0644\u0633\u0624\u0627\u0644 \u0648\u0627\u0644\u062c\u0648\u0627\u0628 \u0643\u0627\u0645\u0644\u064a\u0646 \u0641\u064a \u0635\u0648\u0631 \u0645\u0631\u0642\u0651\u0645\u0629.","\u0635\u0641\u062d\u0629 \xab\u0642\u0631\u0627\u0621\u062a\u064a\xbb: \u0643\u0645 \u0642\u0631\u0623\u062a \u0648\u0643\u0645 \u0628\u0642\u064a \u0641\u064a \u0643\u0644 \u0628\u0627\u0628.","\u0627\u0633\u0645\u0643 \u0623\u0648 \u0643\u0646\u064a\u062a\u0643 \u0627\u062e\u062a\u064a\u0627\u0631\u064a\u0627\u064b \u0645\u0639 \u0623\u0633\u0626\u0644\u062a\u0643 \u0644\u0644\u0634\u064a\u062e."],t.s)
